self.KB_CONTENT["card:758152"]={"id":"card:758152","ty":"card","sourceId":"758152","title":"『請購單建立作業』中的『採購單價 (TB017)』為何？","ver":"iGP","topic":"採購單","keywords":["採購單","品號","單價","大於"],"y":"other","answer":"* 此欄位必須大於等於零。* 該品號有進價管制，故單價不可高於單價上限率。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
