self.KB_CONTENT["field:849168"]={"id":"field:849168","ty":"field","sourceId":"849168","title":"進耗存統計表","ver":"iGP 1.0.14以上","topic":"","keywords":[],"job":"產品成本分析表","code":"","answer":"可將『產品成本分析表』的【內含在製約量及其金額】選項取消，可與『進耗存統計表』的【本期製令入庫額】核對。","file":"fields.jsonl"};
