self.KB_CONTENT["field:781662"]={"id":"field:781662","ty":"field","sourceId":"781662","title":"輸入複製分類碼","ver":"GP4以上","topic":"","keywords":[],"job":"票據底稿產生作業","code":"","answer":"* 指產生傳票時，該張傳票所要賦予之複製分類碼，可點選(icon)或按[F2]開窗查詢片語資料，複製分類碼使用方式請參考會計系統。","file":"fields.jsonl"};
