self.KB_CONTENT["field:753885"]={"id":"field:753885","ty":"field","sourceId":"753885","title":"語言名稱","ver":"iGP","topic":"","keywords":[],"job":"語言代號設定作業","code":"NI002","answer":"* 可開窗點選或[F2]片語資料查詢。","file":"fields.jsonl"};
