self.KB_CONTENT["field:843504"]={"id":"field:843504","ty":"field","sourceId":"843504","title":"產品品號","ver":"GP40.iGP 以上","topic":"","keywords":[],"job":"領料單建立作業","code":"","answer":"『製造命令建立作業-MOCI02』的【產品品號】在『領料單建立作業-MOCI03』中是無法直接修改的，建議若確認此產品品號有誤要更正且製令還未生產，可以直接在『製造命令建立作業-MOCI02』取消確認，修改【產品品號】","file":"fields.jsonl"};
